// Shared types for talking-head edits. Pure TypeScript (no React) so the
// sound-intent exporter can import it in Node.

/** Facts about the ORIGINAL footage, generated by edit_init.py (never hand-edited). */
export type SourceInfo = {
  /** Path inside public/ (a link to the untouched original). */
  readonly src: string;
  readonly sourceWidth: number;
  readonly sourceHeight: number;
  /** The source's own frame rate (r_frame_rate as a number). */
  readonly sourceFps: number;
  readonly sourceDurationSeconds: number;
  /** Approved delivery frame rate (default: the source frame rate). */
  readonly fps: number;
  /** round(sourceDurationSeconds * fps): the edit is exactly as long as the source. */
  readonly durationInFrames: number;
  readonly width: 1080;
  readonly height: 1920;
  /**
   * Optional browser-friendly proxy of the same footage (same fps and duration),
   * used ONLY by the Remotion Player for interactive preview. Renders always use `src`.
   */
  readonly previewSrc?: string;
};

/** Sound intent, in the format scripts/sfx_plan.py reads (times are beat-relative seconds). */
export type SfxIntent = {
  id: string;
  label: string;
  kind: "event" | "movement" | "continuous" | "transition";
  t: number;
  t_end?: number;
  times?: number[];
  category: string | null;
  roles: string[];
  priority: "recommended" | "optional" | "silence-ok";
  note?: string;
  measured_from?: string;
};

export type System = "A" | "B" | "C";

/**
 * Timing contract every beat kind implements (pure functions, no React).
 * `duration` is the beat's length in seconds; `sfx` returns its sound intents
 * measured from the same pose functions the component renders.
 */
export type BeatTiming<P> = {
  readonly system: System;
  /** true if the beat covers the whole frame (System C full-screen). */
  readonly fullscreen: (props: P) => boolean;
  readonly duration: (props: P) => number;
  readonly sfx: (props: P, fps: number) => SfxIntent[];
};

/** One entry of a project's beat list (beats.ts). `at` is seconds on the source timeline. */
export type Beat<K extends string = string, P = unknown> = {
  readonly id: string;
  readonly kind: K;
  readonly at: number;
  readonly props: P;
  /** One line: why this visual exists (story beat -> treatment). */
  readonly reason: string;
  /** Reference IDs from the library this beat is designed from (e.g. ["TXT-001"]). */
  readonly refs: readonly string[];
};
